import React, { useState } from "react";
import { Dashboard } from "./components/Dashboard";
import { Sidebar } from "./components/Sidebar";
import { Header } from "./components/Header";
import { ClientsView } from "./components/ClientsView";
import { WorkerMetrics } from "./components/WorkerMetrics";
import { StatusProvider, useStatus } from "./contexts/StatusContext";

const AppContent: React.FC = () => {
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [currentView, setCurrentView] = useState("dashboard");
  const { state } = useStatus();

  return (
    <div className="min-h-screen bg-gradient-to-br from-secondary-50 to-secondary-100">
      {/* Sidebar */}
      <Sidebar
        isOpen={sidebarOpen}
        onClose={() => setSidebarOpen(false)}
        currentView={currentView}
        onViewChange={setCurrentView}
      />

      {/* Main Content */}
      <div
        className={`transition-all duration-300 ${sidebarOpen ? "lg:ml-64" : "lg:ml-16"}`}
      >
        {/* Header */}
        <Header
          onSidebarToggle={() => setSidebarOpen(!sidebarOpen)}
          sidebarOpen={sidebarOpen}
        />

        {/* Main Dashboard */}
        <main className="p-4 lg:p-6">
          <div className="max-w-7xl mx-auto">
            {currentView === "dashboard" && <Dashboard />}
            {currentView === "clients" && <ClientsView />}
            {currentView === "tasks" && (
              <div className="bg-white rounded-xl shadow-sm p-6">
                <h2 className="text-2xl font-bold text-secondary-900 mb-4">
                  Task Queue
                </h2>
                <p className="text-secondary-600">
                  Task queue interface coming soon...
                </p>
              </div>
            )}
            {currentView === "metrics" && (
              <WorkerMetrics clients={state.clients || []} />
            )}
            {currentView === "settings" && (
              <div className="bg-white rounded-xl shadow-sm p-6">
                <h2 className="text-2xl font-bold text-secondary-900 mb-4">
                  Settings
                </h2>
                <p className="text-secondary-600">
                  Settings interface coming soon...
                </p>
              </div>
            )}
          </div>
        </main>
      </div>

      {/* Mobile sidebar overlay */}
      {sidebarOpen && (
        <div
          className="fixed inset-0 bg-black bg-opacity-50 z-40 lg:hidden"
          onClick={() => setSidebarOpen(false)}
        />
      )}
    </div>
  );
};

function App() {
  return (
    <StatusProvider>
      <AppContent />
    </StatusProvider>
  );
}

export default App;
